/// For every position i in the input vector, if `arr[i] > k` then the output at i is -1,
/// otherwise it is equal to the original `arr[i]`.
#[verifier::external]   // we trust this implementation
#[requires(true)]
#[ensures(result.len() == arr.len())]
#[ensures(
    forall(|i: usize| i < arr.len() ==>
        result[i] == (if arr[i] > k { -1 } else { arr[i] })
    )
)]
fn replace(arr: &Vec<i32>, k: i32) -> Vec<i32> {
    arr.iter()
       .map(|&x| if x > k { -1 } else { x })
       .collect()
}

